/* sys/stat.h for a tree that wants os9lib's real stat().   osk-freeware, 2026-08-24.   COMPAT's own sys/stat.h routes to <UNIX/stat.h>, which pulls in <modes.h>,   and os9lib's <stat.h> refuses to sit beside that one:       stat.h:14: #error Can not include both stat.h and modes.h.   So a recipe cannot simply add os9lib's DEFS to the search path -- the first   <sys/stat.h> it meets takes it down the other road.  This is the forward   that keeps it on os9lib's.  Put -V=/h7/OS9LIB ahead of -V=/h7 and leave   everything else alone; -V=/dd/DEFS/os9lib has to be there too, for the   <stat.h> this reaches.   A recipe using this must NOT also -D the S_IF* names.  os9lib's stat.h   treats a defined S_IFMT as proof that modes.h got in first and stops with   that same #error. */#include <stat.h>